{
  "subtype": "causal_attribution",
  "outcome_variable": "resolution_efficiency (operationalized via resolution_days / is_inefficient)",
  "per_column": [
    {
      "name": "resolution_days",
      "causal_role": "outcome",
      "named_in_query": true,
      "rationale": "Continuous measure of resolution time; a direct operationalization of resolution_efficiency, i.e., the outcome itself, not a cause."
    },
    {
      "name": "is_inefficient",
      "causal_role": "outcome",
      "named_in_query": true,
      "rationale": "Binary flag of inefficient resolution -- this is the focus/outcome discretized, not a treatment or confounder."
    },
    {
      "name": "assignee_mismatch",
      "causal_role": "treatment",
      "named_in_query": false,
      "rationale": "Candidate cause: whether the incident was routed/assigned to the wrong person. Plausibly drives longer resolution and represents an 'underlying issue' whose effect on efficiency is being attributed."
    },
    {
      "name": "is_critical_or_high",
      "causal_role": "confounder",
      "named_in_query": false,
      "rationale": "Priority plausibly affects both routing/assignment (treatment) and resolution time (outcome); high-priority incidents may be escalated differently and resolved faster/slower, so it is a common cause requiring adjustment."
    },
    {
      "name": "state_is_resolved",
      "causal_role": "collider",
      "named_in_query": false,
      "rationale": "Whether the incident reached a resolved state is downstream of the resolution process itself; conditioning on it can induce selection bias, not a legitimate confounder."
    },
    {
      "name": "above_category_median",
      "causal_role": "other",
      "named_in_query": false,
      "rationale": "Defined relative to resolution time within category, so it is essentially a re-expression of the outcome (efficiency benchmarked to category), not an independent common cause."
    },
    {
      "name": "sys_updated_by_is_employee",
      "causal_role": "confounder",
      "named_in_query": false,
      "rationale": "Type of handler (employee vs. other/automated) can influence both who/how the incident is assigned (treatment) and how quickly it is resolved (outcome), making it a plausible common cause; though weaker and possibly a proxy."
    }
  ],
  "treatment_present": true,
  "treatment_columns": ["assignee_mismatch"],
  "confounders": [
    {"name": "is_critical_or_high", "named_in_query": false, "plausibility": 0.6},
    {"name": "sys_updated_by_is_employee", "named_in_query": false, "plausibility": 0.35}
  ],
  "confounder_quality": 0.4,
  "rationale": "A clear treatment (assignee_mismatch) is present, and the query names it via 'underlying issues.' The set does surface at least one plausible common cause of both treatment and outcome not stated in the query (is_critical_or_high, i.e. priority), which is the capability under test; sys_updated_by_is_employee is a weaker candidate confounder. However, several added columns are outcome restatements (resolution_days, is_inefficient, above_category_median), one is a likely collider (state_is_resolved), and no strong caller/category/temporal confounders were surfaced. Overall the causal setup is only partially realized, with modest confounder quality."
}

